<?php
declare(strict_types=1);
require_once __DIR__ . "/crud.php";
/** Use only from a versioned CLI migration; never create tables from a web request. */
function createContentTable(PDO $db, string $table): void
{
    $quoted = crudIdentifier($db, $table);
    $id = match ($db->getAttribute(PDO::ATTR_DRIVER_NAME)) {
        "mysql" => "INT AUTO_INCREMENT PRIMARY KEY",
        "pgsql" => "INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
        default => "INTEGER PRIMARY KEY AUTOINCREMENT",
    };
    $text =
        $db->getAttribute(PDO::ATTR_DRIVER_NAME) === "mysql"
            ? "MEDIUMTEXT"
            : "TEXT";
    $db->exec(
        "CREATE TABLE {$quoted} (id {$id}, title VARCHAR(200) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, excerpt VARCHAR(1000) NOT NULL, content {$text} NOT NULL, details TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', publish_at TIMESTAMP NULL, featured_media_id INTEGER NULL, author_id INTEGER NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, seo_title VARCHAR(70) NOT NULL DEFAULT '', seo_description VARCHAR(170) NOT NULL DEFAULT '', seo_noindex INTEGER NOT NULL DEFAULT 0)",
    );
}
function dropContentTable(PDO $db, string $table): void
{
    $quoted = crudIdentifier($db, $table);
    $query = $db->prepare("DELETE FROM content_media WHERE content_kind=?");
    $query->execute([$table]);
    $query = $db->prepare("DELETE FROM seo_redirects WHERE kind=?");
    $query->execute([$table]);
    $db->exec("DROP TABLE " . $quoted);
}
